import argparse
import hashlib
import json
import subprocess

from edit_vocab import ADD_LINE_DSL,CASE_DSL,SELECTED_CASES,VOCAB,case_prompts,parameters
import pcve_edit_dsl as dsl
from pcve_media_contract import require_video
from scene_paths import REPO,CASE as SCENE_DIR,SUITE_KEY,blender_runtime,output_path


def read(path):
    return json.loads(Path(path).read_text(encoding='utf-8'))


def sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def run_record(config):
    """A solver configuration without the fields that only say where and under which label it ran (and old code hashes)."""
    return {k: v for k, v in config.items() if k not in ('execution_host', 'execution_hostname', 'execution_ip', 'new_revision',
                                                          'source_hashes')}


def repo_path(value):
    value=Path(value)
    return value if value.is_absolute() else REPO/value


def catalog_id(case):
    return 'source' if case=='source' else PCVE_EDITS[case]['catalog_case_id']


def check_catalog():
    """The literal catalog above must equal what edit_vocab.py derives."""
    if list(dsl.editable_objects(VOCAB))!=PCVE_SOURCE['editable_objects']:
        raise RuntimeError('editable_objects differ from edit_vocab.py')
    for case,item in PCVE_EDITS.items():
        edit=dsl.parse(CASE_DSL[case],VOCAB)
        override=dsl.to_physics_override(edit,VOCAB)
        diff={key:{'from':VOCAB.baseline_physics[key],'to':value} for key,value in override.items()}
        # ADD: native_edit_dsl is the native preset DSL (CASE_DSL), edit_dsl the published BETWEEN form.
        published=ADD_LINE_DSL if isinstance(edit,dsl.AddEdit) else CASE_DSL[case]
        if item.get('native_edit_dsl',item['edit_dsl'])!=CASE_DSL[case] or item['edit_dsl']!=published or item['physics_override']!=override or item['physics_diff']!=diff:
            raise RuntimeError(f'{case}: catalog DSL/override differs from edit_vocab.py')
        if item['prompts']!=case_prompts(case):
            raise RuntimeError(f'{case}: catalog prompts differ from the DSL rendering')
        expected=parameters(case)
        for key,value in override.items():
            native={'block_initial_speed_m_s':('block_initial_velocity_m_s',lambda v:v[0]),
                    'bumper_present':('bumper_present',lambda v:[int(v)]),
                    'added_block_present':('added_block_present',lambda v:[int(v)])}.get(key,(key,lambda v:v))
            if native[1](expected[native[0]])!=value:
                raise RuntimeError(f'{case}: {key} does not resolve to the native case value')


def verify(suite,selection):
    """Published suite + the native evidence it was built from, read from their current locations."""
    check_catalog()
    manifest=read(SCENE_DIR/'scene_manifest.json')
    pointer=manifest['canonical_suites'][SUITE_KEY]
    if (REPO/pointer['target']).resolve()!=suite.resolve():
        print(f'note: verifying {suite}, which is not the canonical target {pointer["target"]}',file=sys.stderr)
    native=manifest['native_outputs']
    suite_manifest=read(suite/'suite_manifest.json')
    rows_by_id={row['case_id']:row for row in [suite_manifest['source'],*suite_manifest['edits']]}
    rows=[]
    for case in selection:
        cid=catalog_id(case)
        target=suite/'cases'/cid
        row=rows_by_id[cid]
        video_hash=sha(target/'video.mp4')
        if not (video_hash==pointer['case_video_sha256'][case]==row['video_sha256']==read(target/'provenance.json')['video_sha256']):
            raise RuntimeError(f'{case}: video bytes differ from scene_manifest/suite_manifest/provenance')
        media=require_video(target/'video.mp4')
        prompts=read(target/'prompts.json')
        expected=PCVE_SOURCE if case=='source' else PCVE_EDITS[case]
        if prompts['prompts']!=expected['prompts'] or prompts['edit_dsl']!=expected['edit_dsl']:
            raise RuntimeError(f'{case}: prompts.json differs from the builder catalog')
        gt=read(target/'ground_truth_transforms.json')
        cache=repo_path(native['cache_root'])/case/'simulation.npz'
        cache_hash=sha(cache)
        if gt.get('format_version')!='pcve_ground_truth/1' or len(gt['frames'])!=media['frames'] or \
                any(abs(f['time_sec']-(f['frame_index']-1)/24)>1e-9 for f in gt['frames']):
            raise RuntimeError(f'{case}: ground truth is not the pcve_ground_truth/1 record of the video clock')
        sim=repo_path(native['simulation_root'])/case
        config=read(sim/'simulation_config.json')
        if config['physics']!=parameters(case) or run_record(read(cache.with_name('simulation_config.json')))!=run_record(config):
            raise RuntimeError(f'{case}: solver configuration differs from scene_spec.json or the registered cache')
        for name in ('independent_physics_audit.json','contact_volume_audit.json'):
            audit=read(sim/name)
            if audit['status']!='passed' or not all(audit['checks'].values()):
                raise RuntimeError(f'{case}: {name} did not pass')
        if read(sim/'independent_physics_audit.json')['input_sha256']['simulation.npz']!=cache_hash or \
           read(sim/'contact_volume_audit.json')['cache_sha256']!=cache_hash:
            raise RuntimeError(f'{case}: audits are bound to other cache bytes')
        render=repo_path(native['render_root'])/case
        rendered=read(render/native.get('render_record','render_report.json'))
        rendered_cache=rendered.get('cache_sha256') or sha(rendered['cache'])
        if rendered_cache!=cache_hash:
            raise RuntimeError(f'{case}: the video was rendered from another cache')
        rows.append({'case':case,'catalog_case_id':cid,'video_sha256':video_hash,'cache_sha256':cache_hash,'media':media})
    print(json.dumps({'suite':str(suite),'verified_cases':rows,'status':'VERIFIED'},
                     indent=2,ensure_ascii=False))


if __name__=='__main__':
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--stage',choices=('verify','prepare','encode','determinism','publish','prompts'),default='verify')
    parser.add_argument('--cases',nargs='+',choices=SELECTED_CASES,default=list(SELECTED_CASES))
    parser.add_argument('--suite-root',type=Path,help='suite folder; verify reads the published suite (canonical target in scene_manifest.json) by default, prompts and publish write to renders/wood_block_rubber_stop/suite_build/<suite> by default')
    parser.add_argument('--rerun',type=Path,help='determinism stage: folder with a second solve of every case (<case>/simulation.npz)')
    parser.add_argument('--blender-bin',type=Path,help='publish stage (ground truth of the new suite): Blender (default: tools/blender-4.3.2-linux-x64 when present, else pcve_assets.blender())')
    args=parser.parse_args()
    suite=args.suite_root or REPO/read(SCENE_DIR/'scene_manifest.json')['canonical_suites'][SUITE_KEY]['target']
    build_suite=args.suite_root or REPO/'renders'/PCVE_SCENE/'suite_build'/SUITE_KEY
    tool=[sys.executable,'-B',str(SCENE_DIR/'tools/publish_suite.py')]
    if args.stage=='verify':
        verify(suite,args.cases)
    elif args.stage=='prepare':
        subprocess.run([sys.executable,'-B',str(SCRIPTS/'download_assets.py'),
                        '--scene','rigid_elastic/wood_block_rubber_stop','--check'],check=True)
    elif args.stage=='encode':
        subprocess.run([*tool,'encode','--cases',*args.cases],check=True)
    elif args.stage=='determinism':
        if not args.rerun:
            parser.error('--rerun <folder of the second solve> is required')
        subprocess.run([*tool,'determinism','--rerun',str(args.rerun)],check=True)
    elif args.stage=='publish':
        check_catalog()
        subprocess.run([*tool,'build','--suite',str(output_path(build_suite)),'--blender',str(blender_runtime(args.blender_bin))],check=True)
        verify(build_suite,list(SELECTED_CASES))
    else:
        check_catalog()
        subprocess.run([*tool,'prompts','--suite',str(output_path(build_suite))],check=True)
